INSERT OR IGNORE INTO sources (id, investigation_id, region_id, title, section, key_content, url) VALUES
  ('SPEC.MAIN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'R.SPEC', 'Specification', 'Specification',
   'Required fields: name (1-64 chars, lowercase+hyphens, matches dir) and description (1-1024 chars). Optional: license, compatibility (1-500 chars), metadata (key-value), allowed-tools (experimental, space-separated). Body no restrictions. Dir: SKILL.md + optional scripts/ (executables), references/ (docs), assets/ (templates/images/data). Progressive disclosure: metadata at startup (~100 tokens), body on activate (<5000 tokens), refs on demand. File references: relative paths, one level deep. Validation via skills-ref CLI.',
   'https://agentskills.io/specification'),
  ('BP.MAIN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'R.BEST.PRACTICES', 'Best Practices', 'Best Practices',
   'Start from real expertise: extract from hands-on tasks (steps that worked, corrections, I/O formats, context provided) or synthesize from project artifacts — internal docs/runbooks/style guides, API specs/schemas/configs, code review comments/issue trackers, version control history (patches/fixes), real-world failure cases. Refine with real execution: run against real tasks, read execution traces not just outputs. Three root causes of wasted time: instructions too vague (agent tries multiple approaches), instructions not applying to current task (agent follows anyway), too many options without clear default. Context: add what agent lacks, omit what it knows; design coherent units (function-like scoping); aim for moderate detail (concise stepwise > exhaustive); progressive disclosure with conditional loading. Calibrate control: match specificity to fragility; provide defaults not menus; favor procedures over declarations. Patterns: gotchas, templates, checklists, validation loops, plan-validate-execute, bundling scripts.',
   'https://agentskills.io/skill-creation/best-practices'),
  ('EVALS.MAIN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'R.EVALS', 'Evaluating Skills', 'Evaluating Skills',
   'Test case design: prompt (realistic user message) + expected output (human-readable success) + optional input files. Start with 2-3, vary phrasing/detail/formality, cover edge cases (malformed input, unusual request, ambiguous instructions), use realistic context (file paths, personal context, column names). Store in evals/evals.json with skill_name + evals array (id, prompt, expected_output, files). Baselines: run each eval twice — with_skill/ and without_skill/ (or old_skill/ vs new_skill/). Workspace per iteration: iteration-N/eval-name/with_skill|without_skill/outputs/ + timing.json + grading.json. Captures timing.json (total_tokens, duration_ms). Assertions: verifiable pass/fail checks, added after first run. Good: valid JSON, labeled axes, ≥3 recs. Weak: "output is good", brittle exact phrasing. Grading: PASS/FAIL with concrete evidence (quote/reference output, not opinion). grading.json: assertion_results[] with text/passed/evidence + summary (passed/failed/total/pass_rate). Blind comparison: LLM judge scores both outputs without revealing which is which. Benchmark aggregation: benchmark.json with with_skill/without_skill/delta containing pass_rate/time/tokens (mean + stddev). Delta tells cost (more tokens/time) vs benefit (higher pass rate). Pattern analysis (5 patterns): remove always-pass assertions; investigate always-fail; study pass-with-skill; tighten inconsistent runs (high stddev → ambiguous instructions); check time/token outliers. Human review: feedback.json per eval with specific actionable feedback ("chart missing axis labels" not "looks bad"). Empty feedback = passed. Review actual outputs alongside grades. Iteration loop (5 steps): 1) give signals + SKILL.md to LLM, 2) review+apply changes, 3) rerun in iteration-N+1, 4) grade+aggregate, 5) human review. Stop when satisfied or plateau. Guidelines: generalize from feedback, keep skill lean, explain the why, bundle repeated work. skill-creator Skill automates running evals, grading, aggregating.',
   'https://agentskills.io/skill-creation/evaluating-skills'),
  ('DESC.MAIN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'R.DESCRIPTIONS', 'Optimizing Descriptions', 'Optimizing Descriptions',
   'Triggering nuance: agents only consult skills for tasks needing knowledge beyond basic tools. 4 writing principles: imperative phrasing ("Use this skill when..." not "This skill does..."); focus on user intent not implementation; err on pushy side (list contexts even without explicit domain mention); keep concise (hard 1024-char limit). Query design: 20 queries (8-10 should-trigger, 8-10 should-not). Vary phrasing (casual/formal), explicitness (names domain vs describes need), detail (terse vs context-heavy), complexity (single-step vs multi-step). Most useful should-trigger = non-obvious connection. Near-misses for should-not: share keywords but need different skill (e.g., Excel formula editing for a CSV skill, CSV-to-DB ETL for an analysis skill). Realism tips: file paths, personal context, specific details, casual language/typos. Testing: run with skill installed, check agent invocation. Pass = should_trigger true + invoked, or should_trigger false + not invoked. Run 3x per query, compute trigger rate (threshold 0.5). Automation script with jq. Train/validation ~60/40 split with proportional mix, shuffle randomly, keep fixed. Optimization loop: evaluate both sets, identify train failures only, revise (narrow if false-triggers, broaden if misses, generalize avoid overfitting, restructure if stuck), check 1024-char limit, repeat until train passes or plateau, select best by validation pass rate. Max 5 iterations. Apply: update description, verify under limit, sanity check with fresh queries. skill-creator Skill automates the loop end-to-end.',
   'https://agentskills.io/skill-creation/optimizing-descriptions'),
  ('SCRIPTS.MAIN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'R.SCRIPTS', 'Using Scripts', 'Using Scripts',
   'One-off commands via uvx/pipx/npx/bunx/deno run/go run. Pin versions for reproducibility (@1.0.0). State prerequisites in compatibility frontmatter field. Move complex commands into tested scripts. Self-contained scripts with inline deps: PEP 723 (Python/uv run), Deno npm: (TypeScript), Bun (TypeScript), bundler/inline (Ruby). Reference scripts via relative paths from skill root. --help required, no interactive prompts, helpful error messages. Structured JSON output (delimited over aligned). Separate data (stdout) from diagnostics (stderr). Predictable output size: agents truncate >10-30K chars — default to summary, support --offset/--page, require --output for large output. Idempotency, input constraints with clear errors, dry-run for destructive ops, meaningful exit codes documented in --help, safe defaults with --confirm/--force for destruction.',
   'https://agentskills.io/skill-creation/using-scripts');
